<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Leader; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class LeaderController extends Controller { public function index(){return view('admin.leaders.index',['items'=>Leader::orderBy('sort_order')->paginate(20)]);} public function create(){return view('admin.leaders.form',['item'=>new Leader]);} public function store(Request $r){$d=$this->data($r);$d['is_published']=$r->boolean('is_published');if($r->hasFile('photo'))$d['photo_path']=$r->file('photo')->store('leaders','public');Leader::create($d);return redirect()->route('admin.leaders.index')->with('success','Leader created.');} public function edit(Leader $leader){return view('admin.leaders.form',['item'=>$leader]);} public function update(Request $r,Leader $leader){$d=$this->data($r);$d['is_published']=$r->boolean('is_published');if($r->hasFile('photo')){if($leader->photo_path)Storage::disk('public')->delete($leader->photo_path);$d['photo_path']=$r->file('photo')->store('leaders','public');}$leader->update($d);return redirect()->route('admin.leaders.index')->with('success','Leader updated.');} public function destroy(Leader $leader){if($leader->photo_path)Storage::disk('public')->delete($leader->photo_path);$leader->delete();return back()->with('success','Leader deleted.');} private function data(Request $r){return $r->validate(['name'=>'required|string|max:150','role'=>'required|string|max:150','department'=>'nullable|string|max:150','biography'=>'nullable|string|max:8000','photo'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:5120','phone'=>'nullable|string|max:50','email'=>'nullable|email|max:255','facebook_url'=>'nullable|url|max:500','instagram_url'=>'nullable|url|max:500','x_url'=>'nullable|url|max:500','sort_order'=>'nullable|integer|min:0','is_published'=>'nullable|boolean']);} }
